CREATE TRIGGER kids_school_issue_insert BEFORE INSERT ON kids_school_issues WHEN NEW.code<>'attendance_support_missing' OR NEW.cleared_at IS NOT NULL OR NOT EXISTS(SELECT 1 FROM kids_hosted_batches b JOIN kids_state k ON k.user_id=b.owner_user_id AND k.id=b.workspace_id WHERE b.id=NEW.batch_id AND b.owner_user_id=NEW.owner_user_id AND b.workspace_id=NEW.workspace_id AND b.status='ready' AND b.expires_at>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND b.epoch=k.epoch AND EXISTS(SELECT 1 FROM kids_school_assertions a WHERE a.owner_user_id=k.user_id AND a.workspace_id=k.id AND a.source_key=NEW.source_key AND a.context_id=NEW.context_id AND a.child_id=NEW.child_id) AND (EXISTS(SELECT 1 FROM kids_hosted_batch_members m WHERE m.batch_id=b.id AND m.chat_id||':'||m.message_id=NEW.source_key AND m.fingerprint=NEW.fingerprint) OR EXISTS(SELECT 1 FROM kids_hosted_history_batch_members m WHERE m.batch_id=b.id AND m.chat_id||':'||m.message_id=NEW.source_key AND m.fingerprint=NEW.fingerprint)))
BEGIN SELECT RAISE(ABORT,'KIDS_SCHOOL_ISSUE_IDENTITY'); END;
