CREATE TRIGGER kids_school_issue_update BEFORE UPDATE ON kids_school_issues WHEN NEW.owner_user_id IS NOT OLD.owner_user_id OR NEW.workspace_id IS NOT OLD.workspace_id OR NEW.source_key IS NOT OLD.source_key OR NEW.context_id IS NOT OLD.context_id OR NEW.child_id IS NOT OLD.child_id OR NEW.code<>'attendance_support_missing' OR NOT ((NEW.cleared_at IS NULL AND EXISTS(SELECT 1 FROM kids_hosted_batches b JOIN kids_state k ON k.user_id=b.owner_user_id AND k.id=b.workspace_id WHERE b.id=NEW.batch_id AND b.owner_user_id=NEW.owner_user_id AND b.workspace_id=NEW.workspace_id AND b.status='ready' AND b.expires_at>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND b.epoch=k.epoch AND EXISTS(SELECT 1 FROM kids_school_assertions a WHERE a.owner_user_id=k.user_id AND a.workspace_id=k.id AND a.source_key=NEW.source_key AND a.context_id=NEW.context_id AND a.child_id=NEW.child_id) AND (EXISTS(SELECT 1 FROM kids_hosted_batch_members m WHERE m.batch_id=b.id AND m.chat_id||':'||m.message_id=NEW.source_key AND m.fingerprint=NEW.fingerprint) OR EXISTS(SELECT 1 FROM kids_hosted_history_batch_members m WHERE m.batch_id=b.id AND m.chat_id||':'||m.message_id=NEW.source_key AND m.fingerprint=NEW.fingerprint)))) OR (OLD.cleared_at IS NULL AND NEW.cleared_at IS NOT NULL AND NEW.batch_id=OLD.batch_id AND NEW.fingerprint=OLD.fingerprint AND NEW.code=OLD.code AND NEW.created_at=OLD.created_at AND EXISTS(SELECT 1 FROM kids_state k JOIN kids_operation_receipts r ON r.owner_user_id=k.user_id AND r.workspace_id=k.id AND r.committed_revision=k.revision JOIN kids_hosted_batches b ON b.id=json_extract(r.source_authority,'$.batchId') WHERE k.user_id=OLD.owner_user_id AND k.id=OLD.workspace_id AND json_extract(r.source_authority,'$.kind')='hosted-source-batch-v1' AND b.owner_user_id=k.user_id AND b.workspace_id=k.id AND b.status='saved' AND (EXISTS(SELECT 1 FROM kids_hosted_batch_members m WHERE m.batch_id=b.id AND m.chat_id||':'||m.message_id=NEW.source_key) OR EXISTS(SELECT 1 FROM kids_hosted_history_batch_members m WHERE m.batch_id=b.id AND m.chat_id||':'||m.message_id=NEW.source_key)))))
BEGIN SELECT RAISE(ABORT,'KIDS_SCHOOL_ISSUE_IMMUTABLE'); END;
