CREATE TRIGGER kids_school_issue_delete BEFORE DELETE ON kids_school_issues WHEN EXISTS(SELECT 1 FROM kids_state WHERE user_id=OLD.owner_user_id AND id=OLD.workspace_id)
BEGIN SELECT RAISE(ABORT,'KIDS_SCHOOL_HISTORY_REQUIRED'); END;

