CREATE TRIGGER kids_school_draft_insert BEFORE INSERT ON kids_school_drafts
WHEN NEW.status<>'pending' OR NEW.applied_operation IS NOT NULL OR length(NEW.request_hash)<>64 OR length(NEW.proposal_hash)<>64 OR length(NEW.source_hash)<>64 OR length(NEW.source_text)>16000 OR length(NEW.source_text)=0 OR NOT json_valid(NEW.proposal_json)
 OR NOT EXISTS(SELECT 1 FROM kids_state k JOIN kids_operation_receipts r ON r.owner_user_id=k.user_id AND r.workspace_id=k.id JOIN kids_service_access a ON a.owner_user_id=k.user_id AND a.workspace_id=k.id WHERE k.user_id=NEW.owner_user_id AND k.id=NEW.workspace_id AND k.revision=NEW.created_revision AND r.operation_id=NEW.operation_id AND r.body_hash=NEW.request_hash AND r.committed_revision=NEW.created_revision AND r.created_at=NEW.created_at AND json_extract(r.source_authority,'$.kind')='parent-calendar-draft-v1' AND json_extract(r.source_authority,'$.consentVersion')='calendar-draft-v1-2026-10-24' AND json_extract(r.source_authority,'$.parentConfirmed')=1 AND json_extract(r.source_authority,'$.draftId')=NEW.id AND json_extract(r.source_authority,'$.serviceGrantId')=NEW.service_grant_id AND json_extract(r.source_authority,'$.serviceRevision')=NEW.service_revision AND a.grant_id=NEW.service_grant_id AND a.revision=NEW.service_revision AND a.revoked_at IS NULL AND a.created_at<=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND ((a.kind='beta' AND a.beta_until>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)) OR (a.kind='subscription' AND EXISTS(SELECT 1 FROM workspace_billing b WHERE b.owner_user_id=a.owner_user_id AND b.workspace_id=a.billing_workspace_id AND b.status='active' AND b.paid_through>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND b.verified_at<=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER) AND b.verified_at>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)-300000 AND b.requested_generation=b.verified_generation AND b.lease_token IS NULL))) AND NOT EXISTS(SELECT 1 FROM json_each(NEW.proposal_json,'$.childIds') c WHERE NOT EXISTS(SELECT 1 FROM json_each(k.document,'$.children') p WHERE json_extract(p.value,'$.id')=c.value)) AND (SELECT COUNT(*) FROM kids_school_drafts WHERE owner_user_id=k.user_id AND workspace_id=k.id AND status='pending' AND expires_at>CAST((julianday('now')-2440587.5)*86400000 AS INTEGER))<5 AND ((SELECT COUNT(*) FROM kids_school_drafts WHERE owner_user_id=k.user_id AND workspace_id=k.id)+(SELECT COUNT(*) FROM kids_school_calendars WHERE owner_user_id=k.user_id AND workspace_id=k.id))<100 AND COALESCE((SELECT SUM(raw_bytes+2048) FROM kids_school_drafts WHERE owner_user_id=k.user_id AND workspace_id=k.id),0)+(SELECT COUNT(*)*512 FROM kids_school_calendars WHERE owner_user_id=k.user_id AND workspace_id=k.id)+NEW.raw_bytes+2048<=4194304)
BEGIN SELECT RAISE(ABORT,'KIDS_SCHOOL_DRAFT_AUTHORITY'); END;
